const CLASSES = ["pothole", "crack", "manhole"];
const raw = $input.first().json;
const body = raw && typeof raw.body === "object" && raw.body !== null && !Array.isArray(raw.body) ? raw.body : null;
const errors = [];
let detections = [];
let counts = { pothole: 0, crack: 0, manhole: 0 };
let confs = [];
if (!body || Object.keys(body).length === 0) {
  errors.push("Request body is missing, empty, or not a JSON object.");
} else {
  const list = Array.isArray(body.detections) ? body.detections : Array.isArray(body.predictions) ? body.predictions : Array.isArray(body.results) ? body.results : null;
  if (list === null) {
    errors.push("No detections array found (expected detections, predictions or results).");
  } else {
    list.forEach((d, i) => {
      if (typeof d !== "object" || d === null) { errors.push("Detection " + i + " is not an object."); return; }
      const labelRaw = d.class_name ?? d.label ?? d.class ?? d.name;
      const label = typeof labelRaw === "string" ? labelRaw.trim().toLowerCase() : "";
      const confRaw = d.confidence ?? d.conf ?? d.score;
      const conf = typeof confRaw === "number" ? confRaw : (typeof confRaw === "string" && confRaw.trim() !== "" ? Number(confRaw) : NaN);
      if (!CLASSES.includes(label)) errors.push("Detection " + i + " has an unknown or missing class label.");
      if (!Number.isFinite(conf) || conf < 0 || conf > 1) errors.push("Detection " + i + " has a confidence that is not a number between 0 and 1.");
      if (CLASSES.includes(label) && Number.isFinite(conf) && conf >= 0 && conf <= 1) {
        counts[label] += 1;
        confs.push(conf);
        detections.push({ class_name: label, confidence: conf, bbox_xyxy: d.bbox_xyxy ?? d.bbox ?? null });
      }
    });
  }
}
const valid = errors.length === 0;
const total = detections.length;
const b = body || {};
const out = {
  is_valid: valid,
  errors: errors,
  inspection_id: b.inspection_id ?? b.id ?? ("exec-" + $execution.id),
  timestamp: b.timestamp ?? new Date().toISOString(),
  source: b.source ?? "unspecified",
  total_detections: total,
  pothole_count: counts.pothole,
  crack_count: counts.crack,
  manhole_count: counts.manhole,
  detections: detections,
  confidence_summary: total > 0 ? { min: Math.min(...confs), max: Math.max(...confs), avg: confs.reduce((a, c) => a + c, 0) / total } : null,
  status: !valid ? "invalid" : total > 0 ? "detected" : "clear",
};
return [{ json: out }];

